// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount, address target) public {
        amount = bound(amount, 1, address(c).balance + 100 ether);
        vm.assume(target != address(0) && target != address(c));
        Reverter adv = new Reverter();
        vm.deal(address(this), amount + 1 ether);
        vm.prank(address(this));
        (bool funded,) = address(c).call{value: amount + 1 ether}("");
        require(funded, "funding failed");
        address originalOwner = c.owner();
        bool ok;
        vm.prank(address(this));
        try c.sendMoney(address(adv), amount) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert("always fails");
    }
}
